const payload = $input.first().json.body || $input.first().json;

const action = (payload.action || 'UPLOAD_PHOTOS').toUpperCase();
const siteName = (payload.siteName || 'General Site').trim();
const stage = (payload.stage || 'General_Work').trim();
const workType = payload.workType || 'Both';
const notes = payload.notes || 'Site photo archive';
const senderPhone = payload.senderPhone || payload.from || '+919361599097';
const recipientJid = payload.replyJid || payload.remoteJid || '919361599097@s.whatsapp.net';
const isGroup = Boolean(payload.isGroup || (recipientJid && recipientJid.endsWith('@g.us')));

// Stage name Tamil mapping
const stageTamilMap = {
  'Roof_Concrete_Pipes': 'ரூஃப் கான்கிரீட் பைப்ஸ் (Roof Slab Piping)',
  'Wall_Chasing_Pipes': 'சுவர் கார்டி & கன்சீல்டு பைப்ஸ் (Wall Chasing / Conduit)',
  'Bathroom_Plumbing': 'பாத்ரூம் பிளம்பிங் (Bathroom Under-tile Plumbing)',
  'Drainage_Sewage': 'டிரைனேஜ் & கழிவுநீர் பைப்ஸ் (Drainage & Chamber)',
  'Main_DB_Wiring': 'மெயின் டிபி & வயரிங் (Main DB & Earthing)',
  'General_Work': 'பொதுவான வேலை (General Work)'
};

const stageTamil = stageTamilMap[stage] || stage;
const timestamp = new Date().toISOString();
const dateOnly = timestamp.split('T')[0];

// Generate Google Drive Folder Name & Link
const sanitizedSite = siteName.replace(/[^a-zA-Z0-9]/g, '_');
const sanitizedStage = stage.toLowerCase();
const driveFolderUrl = `https://drive.google.com/drive/folders/MEP_${sanitizedSite}_${sanitizedStage}`;

// Generate WhatsApp confirmation text
const confirmationText = `✅ *${siteName} சைட் போட்டோக்கள் வெற்றிகரமாகச் சேமிக்கப்பட்டன!*\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📍 *சைட்:* ${siteName}\n` +
  `🔧 *பிரிவு:* ${stageTamil}\n` +
  `👷 *வேலை விபரம்:* ${workType}\n` +
  `📅 *தேதி:* ${dateOnly}\n` +
  `📝 *குறிப்பு:* ${notes}\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📁 *Google Drive Vault:* ${driveFolderUrl}\n` +
  `_நிரந்தரமாக Google Drive & Google Sheet-ல் பதிவு செய்யப்பட்டது._`;

return [{
  json: {
    ...payload,
    action,
    siteName,
    stage,
    stageTamil,
    workType,
    notes,
    senderPhone,
    recipientJid,
    isGroup,
    timestamp,
    dateOnly,
    driveFolderUrl,
    confirmationText
  }
}];
